import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.BM5YPQmL.js";const u=JSON.parse('{"title":"Roadmap","description":"","frontmatter":{},"headers":[],"relativePath":"roadmap.md","filePath":"roadmap.md","lastUpdated":1793722140000}'),i={name:"roadmap.md"};function d(s,e,n,c,l,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="roadmap" tabindex="-1">Roadmap <a class="header-anchor" href="#roadmap" aria-label="Permalink to &quot;Roadmap&quot;">​</a></h1><p>Ordered by the tie-breakers in <code>SOUL.md</code>: the user&#39;s safety and agency first, protocol conformance second, the applet developer&#39;s ability to build third. Nothing here is dated. An item moves off this page when its scenarios pass and its docs exist.</p><h2 id="_1-upstream-pull-requests-to-kehto" tabindex="-1">1. Upstream pull requests to kehto <a class="header-anchor" href="#_1-upstream-pull-requests-to-kehto" aria-label="Permalink to &quot;1. Upstream pull requests to kehto&quot;">​</a></h2><p>Each item shrinks kernl when it lands; see <a href="./alpha-status#upstream-gaps">Alpha status</a>.</p><ul><li>Forward <code>getFocusContext</code>, <code>onFirewallEvent</code> and <code>firewallPersistence</code> through <code>ShellAdapter</code> so the runtime&#39;s own firewall can be focus-aware without a second engine in front of it.</li><li>Let the host choose the ACL default policy in <code>createRuntime</code>, so a restrictive shell does not have to write every capability explicitly.</li><li>Offer a pre-dispatch hook on port traffic, so the visibility gate can hold a hidden applet&#39;s envelopes instead of observing them after dispatch.</li><li>Expose a setter for the runtime firewall&#39;s <code>unfocusedMultiplier</code>, so the profile&#39;s focus tightening applies before dispatch as well as after.</li></ul><h2 id="_2-bridge-backends" tabindex="-1">2. Bridge backends <a class="header-anchor" href="#_2-bridge-backends" aria-label="Permalink to &quot;2. Bridge backends&quot;">​</a></h2><p>Each backend plugs into the path the HTTP bridge already exercises end to end. Order reflects how much of the user&#39;s exposure each one changes; see <a href="./concepts/bridges">Bridges</a>.</p><table tabindex="0"><thead><tr><th>Backend</th><th>Interface</th><th>Notes</th></tr></thead><tbody><tr><td>Mail</td><td><code>MailBackend</code></td><td>Opens or creates a conversation for a <code>mailto:</code> locator. Candidate for a shell-side IMAP/JMAP client or a hand-off to a configured mail account.</td></tr><tr><td>NZB</td><td><code>NzbBackend</code></td><td>Hands an <code>nzb:</code> locator to a configured downloader. The downloader runs outside the browser; the bridge reports job state.</td></tr><tr><td>Torrent</td><td><code>TorrentBackend</code></td><td>Adds an info hash with its trackers. WebTorrent in the shell, or a configured external client. Marked as public activity in the exposure description.</td></tr><tr><td>Soulseek</td><td><code>SoulseekBackend</code></td><td>Requests one file from one peer. Requires a daemon; the bridge reports job state.</td></tr></tbody></table><h2 id="_3-messaging" tabindex="-1">3. Messaging <a class="header-anchor" href="#_3-messaging" aria-label="Permalink to &quot;3. Messaging&quot;">​</a></h2><ul><li>Supply the double-ratchet runtime so the <code>ratchet</code> provider reports <code>available</code>. Its properties are already described; see <a href="./concepts/messaging">Messaging</a>.</li><li>Per-conversation provider migration: move a correspondent from <code>legacy</code> to <code>private</code> when both clients can read it, shown as a reversible choice.</li></ul><h2 id="_4-mobile-layouts" tabindex="-1">4. Mobile layouts <a class="header-anchor" href="#_4-mobile-layouts" aria-label="Permalink to &quot;4. Mobile layouts&quot;">​</a></h2><p>The window manager contracts come from <code>@kehto/wm</code>. A narrow-viewport layout with a window switcher, gestures for focus and dismissal, and the same visibility semantics the guard relies on (a window off screen is hidden, and hidden windows are deferred).</p><h2 id="_5-account-switching" tabindex="-1">5. Account switching <a class="header-anchor" href="#_5-account-switching" aria-label="Permalink to &quot;5. Account switching&quot;">​</a></h2><p><code>AccountManager</code> already holds several accounts. The missing piece is a switcher that makes the active account visible on every screen, keeps grants scoped to the account that gave them, and never signs a write with an account the user did not pick for that window.</p><h2 id="_6-guard" tabindex="-1">6. Guard <a class="header-anchor" href="#_6-guard" aria-label="Permalink to &quot;6. Guard&quot;">​</a></h2><ul><li>Per-applet guard profiles: today the profile is shell-wide and resets to <code>strict</code> on boot (D-003). Next: an override per applet identity, remembered locally.</li><li>Re-narrow a live applet&#39;s advertised environment when a domain is revoked; today the ACL denies at once but <code>shell.init</code> only changes on the next open.</li><li>Bridge consent per host: wire <code>createDefaultBridges({ authorize })</code> to a host prompt so a granted <code>resource</code> request still asks before reaching a new origin.</li><li>Persist per-applet profile overrides and grants through a user-chosen sync, so loosening an applet once does not have to be repeated per device.</li><li>A readable guard log in the shell: every <code>defer</code>, <code>reject</code>, <code>quarantine</code> and <code>flag</code> event, with the stable reason and the applet it concerned.</li></ul><h2 id="not-planned" tabindex="-1">Not planned <a class="header-anchor" href="#not-planned" aria-label="Permalink to &quot;Not planned&quot;">​</a></h2><ul><li>A global configuration flag that loosens a mitigation for every applet. <code>SOUL.md</code> opinion three rules it out.</li><li>A second event library beside applesauce. <code>DECISIONS.md</code> D-002 rules it out.</li><li>A &quot;recommended&quot; messaging provider. D-009 rules it out.</li></ul>',18)])])}const m=t(i,[["render",d]]);export{u as __pageData,m as default};
